export const sourcePages = {
  "93": "<h2>93</h2>\n<h3><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第5回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">ロシアと東方問題</strong></span></h3>\n<p>ここまで続けて19世紀のヨーロッパ各国の状況を見てきたけど、いよいよ今回でひと区切り、最後は<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ロシア</u>だ。ロシアってもともとは遅れた国だったから、ヨーロッパの国際関係にはあまり登場してこなかったけど、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">19世紀に入るといよいよ国際政治の表舞台に出てくる</u>よ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">大きくつかもう！</strong></span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span></td><td><strong class=\"source-bold\">ロシアのツァーリズム</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">94〜95ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span></td><td><strong class=\"source-bold\">東方問題の発生</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">95〜101ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span></td><td><strong class=\"source-bold\">クリミア戦争とロシアの改革</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">102〜105ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span></td><td><strong class=\"source-bold\">露土戦争</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">105〜107ページ</span></td></tr></tbody></table></div>\n<blockquote><p>今回のポイントはロシアの南下政策VS.イギリスだよ</p></blockquote>\n<p>18世紀後半に登場した<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">エカチェリーナ2世</u>による近代化や、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ナポレオン戦争</u>で活躍したこともあって、19世紀に入ると、ついに<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ロシアがヨーロッパの5大国の1国になった</u>。とはいっても中身は……全然変わってない。<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">絶対王政時代の体制がそのまま残っていて</u>、自由も平等も知ったこっちゃない。しかも、領土拡大のために進めた<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">南下政策はイギリスとの激しい対立を生む</u>んだ。これは、バルカン半島を中心とする<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">オスマン帝国領をめぐって争われた</u>から、ヨーロッパから見ると東側。だから「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">東方問題</u>」って呼ばれているよ。ロシアと東方問題……最強国イギリスを敵に回しちゃったロシアはどうなるんだろ？　ここで繰り広げられた戦争は、ロシアだけじゃなくて、ヨーロッパ全体に影響していくよ。それじゃあ、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ロシアと東方問題</u>の始まり〜。</p>",
  "94": "<h2>94</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第5回</strong></span> ロシアと東方問題</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <strong class=\"source-bold\">ロシアのツァーリズム</strong></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ナポレオン戦争が終わって……でも、ロシアは何も変わらん！</strong></span></h4>\n<p>ヨーロッパの一番東にある<strong class=\"source-bold\">ロシア</strong>は、<strong class=\"source-bold\">ヨーロッパのなかでも一番遅れている国</strong>だった。<strong class=\"source-bold\">ピョートル1世</strong>や<strong class=\"source-bold\">エカチェリーナ2世</strong>が「ロシアを近代化しよ〜」と<ruby>頑張<rt>がんば</rt></ruby>っていたけど、西ヨーロッパみたいに商業や工業が盛んになっていたわけじゃないから、近代化のためのお金が足りない。じゃあどうするか？　歴代のロシア皇帝は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>農奴<rt>のうど</rt></ruby>制</strong></span>の強化によって財源を確保し、<ruby>専制<rt>せんせい</rt></ruby>政治を強化したんだ。簡単に言うと「<strong class=\"source-bold\">農民から絞りとった穀物を輸出して得たお金で皇帝を強くする！</strong>」ってことだね。これがロシア皇帝（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ツァーリ</strong></span>）による専制政治、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ツァーリズム</strong></span>だよ。</p>\n<p>こんなことばっかりやっていたから、<strong class=\"source-bold\">各国が近代的な市民社会に向かって</strong>少しずつ工業化を進め始めたころにも、<strong class=\"source-bold\">ロシアは何も変わらなかった</strong>。「市民階級？　何それ？　産業革命？　それおいしいの？」みたいな感じ。結局、農奴が土地に縛りつけられているから、工業化しようとしたって<strong class=\"source-bold\">労働者もいない</strong>し、工場を経営するような<strong class=\"source-bold\">資本家も全然育っていなかった</strong>。</p>\n<p>19世紀初め、ナポレオン軍と戦ったロシアは、<strong class=\"source-bold\">アウステルリッツの戦い</strong>で負けてボコボコになったはずなんだけど、<strong class=\"source-bold\">ロシア遠征</strong>では冬の寒さを味方につけて、しかも「<ruby>侵略<rt>しんりゃく</rt></ruby>者から祖国ロシアを守る！」という意識も盛り上がり、<strong class=\"source-bold\">最終的に勝った</strong>よね。<strong class=\"source-bold\">この勝利がナポレオンの失脚を早めた</strong>から、以後ロシアは国際的な地位を上げて、<strong class=\"source-bold\">ヨーロッパの5大国の一角</strong>に数えられるようになったんだ。</p>\n<p>そしてロシア皇帝<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アレクサンドル1世</strong></span>は、<strong class=\"source-bold\">ウィーン会議</strong>においてオーストリアのメッテルニヒとともに<strong class=\"source-bold\">保守反動体制の中心</strong>となり、1815年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>神<rt>しん</rt></ruby><ruby>聖<rt>せい</rt></ruby>同盟</strong></span>を提唱、各国の君主と連携して<strong class=\"source-bold\">自由主義や国民主義を<ruby>潰<rt>つぶ</rt></ruby>そうとした</strong>んだね。だから、彼の死をきっかけに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">デカブリストの乱</strong></span>が起きたんだけど、新しく皇帝になった<strong class=\"source-bold\">ニコライ1世</strong>に<ruby>鎮圧<rt>ちんあつ</rt></ruby>されてしまったんだ。</p>\n<blockquote><p>ツァーリズムのロシアは、自由・平等大キライ！　他の国にまで弾圧に行くよ……</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">新皇帝ニコライ1世もツァーリズム！「ヨーロッパの<ruby>憲兵<rt>けんぺい</rt></ruby>」って？</strong></span></h4>\n<p>アレクサンドル1世のあとに即位した<strong class=\"source-bold\">ニコライ1世</strong>の時代も、結局何も変わらなかった、というか<strong class=\"source-bold\">むしろ悪化してる</strong>。彼が即位したのは1825年だから、5年後には<strong class=\"source-bold\">フランスの七月革命の影響</strong>でヨーロッパ全体で<strong class=\"source-bold\">自由主義が高揚</strong>し、この影響がロシア領にも飛び火して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーランド反乱</strong></span>が起こったよね。だって、ロシアの支配下でひどい目にあわされてるんだもん。これを<strong class=\"source-bold\">ロシアは徹底的に<ruby>弾圧<rt>だんあつ</rt></ruby>した</strong>けど、<strong class=\"source-bold\">命令したのがニコライ1世だ</strong>。さらに、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1848年革命</strong></span>では、ロシア領だけじゃなくて、<strong class=\"source-bold\">他の国の領内の民族運動まで鎮圧</strong>しに行ったよ……覚えてるかなぁ……オーストリア</p>",
  "95": "<h2>95</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">東方問題の発生</u></p>\n<p>領だった<strong class=\"source-bold\">ハンガリーの民族運動を鎮圧</strong>するのに<strong class=\"source-bold\">ロシア軍が協力</strong>したよね。こんなふうに、ヨーロッパ全体の民族運動を鎮圧していったから、この時期のロシアは「<strong class=\"source-bold\">ヨーロッパの憲兵</strong>」って呼ばれているよ。特にオーストリアのメッテルニヒが失脚したあとは、<strong class=\"source-bold\">ニコライ1世がヨーロッパの反動体制の中心</strong>になったんだよ。憲兵っていうのは「軍警察」。軍隊が警察になって厳しい取り締まりをするのね。反発したヤツは消すの……怖いな。</p>\n<p>ヨーロッパ全体に対してもこんな状態だから、<strong class=\"source-bold\">国内支配も厳しい</strong>よ。本物の憲兵がいて、反対する連中は全部潰しながら、<strong class=\"source-bold\">農奴制を基盤とする保守反動政治</strong>で、皇帝権を強化していったんだね。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <strong class=\"source-bold\">東方問題の発生</strong></h3>\n<h4><strong class=\"source-bold\">〈ロシアの南下政策と列強の対立〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">イギリス</strong></td><td><strong class=\"source-bold\">オーストリア</strong></td></tr><tr><td><strong class=\"source-bold\">ロシア帝国</strong></td><td><strong class=\"source-bold\">エジプト</strong></td></tr><tr><td><strong class=\"source-bold\">インド</strong></td><td><strong class=\"source-bold\">ダーダネルス・ボスフォラス海峡</strong></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">イギリスの最重要植民地</span></td><td></td></tr><tr><td><span data-source-marker=\"dashed-arrow\" style=\"color:#e52715\">┄➜</span> イギリスのインド航路</td><td><span data-source-marker=\"arrow\" style=\"color:#001000\">➜</span> ロシアの南下政策</td></tr></tbody></table></div>\n<blockquote><p>イギリスとロシアは世界中で対立するよ！</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ロシアの南下政策VS.イギリス。絶対に譲れない両国の<ruby>理由<rt>わけ</rt></ruby>とは？</strong></span></h4>\n<p>続いて今回のヤマ場、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東方問題</strong></span>に進もう。その前に、まずは東方問題で激しく対立した<strong class=\"source-bold\">ロシアとイギリスの事情</strong>について解説しておこう。</p>\n<p><strong class=\"source-bold\">ロシア</strong>は<strong class=\"source-bold\">ピョートル1世がアゾフ海に進出</strong>して以来、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南下政策</strong></span>を進めていたんだ。南下政策っていうのは要するに「<strong class=\"source-bold\">南へと勢力を拡大していく</strong>」ってことだけど、まぁロシアは北に行っても北極しかないからね。だから領土を獲得するなら南、ってことになる。そして、<strong class=\"source-bold\">エカチェリーナ2世</strong>がオスマン帝国から<strong class=\"source-bold\">クリミア＝ハン国【クリム＝ハン国】を奪って黒海の支配権を確保</strong>し、さらに<strong class=\"source-bold\">ギリシア正教徒の保護権</strong>を得ると（<strong class=\"source-bold\">キュチュク＝カイナルジ条約</strong>）、ロシアはこれを口実に、<strong class=\"source-bold\">オス</strong></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "96": "<h2>96</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第5回</strong></span> ロシアと東方問題</p>\n<p><strong class=\"source-bold\">マン帝国領への進出</strong>を<ruby>狙<rt>ねら</rt></ruby>い始めるんだ。これはよく「<ruby>不凍港<rt>ふとうこう</rt></ruby>（冬になっても凍らない港）を取りたい」って説明されてるけど、それだけじゃないんだよ。だって、港を取ったあともロシアの遠征が続くんだもん。ウラには、ツァーリズムで生じた<strong class=\"source-bold\">国内の矛盾を対外遠征でごまかす</strong>っていう意図もあるからね。じゃなきゃ、負け続けてるのにロシアがひたすら遠征をする意味がわかんないでしょ。そして、19世紀には<strong class=\"source-bold\">地中海への進出を狙う</strong>んだけど、これが<strong class=\"source-bold\">イギリスとの激しい対立</strong>を引き起こすよ。</p>\n<p>続いて<strong class=\"source-bold\">イギリス</strong>の事情を見ていこう。アメリカ独立後、<strong class=\"source-bold\">イギリスにとって一番大事な植民地はインド</strong>となり、<strong class=\"source-bold\">インドへ向かう航路の確保</strong>が重要な戦略になった。このためインドへの交通路として、<strong class=\"source-bold\">地中海からエジプトを経由して、紅海からインド洋に抜ける航路</strong>（地図<span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">➡P.95</strong></span>の赤の点線だよ）は絶対に譲れない。ちなみに、ナポレオンがエジプト遠征をやったのは、イギリスにこの航路を確保させないためだ。</p>\n<p>こう考えたときに、当時の<strong class=\"source-bold\">イギリスにとって一番危ない敵</strong>は誰か？　ズバリ、<strong class=\"source-bold\">ロシア</strong>なんだよ。<strong class=\"source-bold\">ロシアが黒海から地中海に進出</strong>しようとすると、イギリスが確保しようとしている地中海の航路の安全が<ruby>脅<rt>おびや</rt></ruby>かされる。さらに、<strong class=\"source-bold\">ロシアが中央アジアやイランへの南下政策</strong>を進めると……インドそのものが危ない。<strong class=\"source-bold\">イギリスはインドを狙うヤツは絶対に許さない</strong>。こうして、19世紀の国際関係では、<strong class=\"source-bold\">ロシアの南下と、それを絶対に阻止したいイギリスの対立</strong>が、もっとも重大な問題だったんだよ。特にインド防衛をめぐる英露の対立は「<strong class=\"source-bold\">グレートゲーム</strong>」と呼ばれているんだ。</p>\n<blockquote><p>いよいよ、イギリスとロシアの対立が激化してきたね。このあとどうなるんだろ？</p></blockquote>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">じゃあ、東方問題ってなんだろう？</strong></span></h4>\n<p>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東方問題</strong></span>」ってのはヨーロッパがつけた名前だから、ヨーロッパから見て東側にある<strong class=\"source-bold\">オスマン帝国領をめぐる問題</strong>だ。1699年の<strong class=\"source-bold\">カルロヴィッツ条約</strong>以来、<strong class=\"source-bold\">オスマン帝国が衰退</strong>してくると、<strong class=\"source-bold\">オーストリアやロシア</strong>がその領土への進出を始めていたよね。そして19世紀になると、フランス革命やナポレオン戦争、さらにはラテンアメリカの独立などの影響で<strong class=\"source-bold\">自由主義やナショナリズムが拡大</strong>し、オスマン帝国に支配されていた<strong class=\"source-bold\">ヨーロッパの諸民族（キリスト教徒）が、イスラーム国家のオスマン帝国からの独立を目指す民族運動を始めた</strong>んだよ。舞台は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バルカン半島</strong></span>だ。</p>\n<p>オスマン帝国支配下のバルカン半島には、カトリック教徒もいればギリシア正教徒もいる。さらにはヨーロッパで差別されたユダヤ人もいる。彼らはジズヤさえ納めれば信仰を認められたから、独自の共同体をつくって信仰を守っていた（これは<strong class=\"source-bold\">ミッレット</strong>と呼ばれていたよね）。そして彼らがオスマン帝国からの独立を要求し始めると、「<strong class=\"source-bold\">カトリック教徒</strong>を助けろ〜」って言ってかつて<ruby>神聖<rt>しんせい</rt></ruby>ローマ皇帝だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オーストリア</strong></span>が<ruby>介入<rt>かいにゅう</rt></ruby>してくる一方、「<strong class=\"source-bold\">ギリシア正教徒</strong>をいじめるんじゃない！」っ</p>",
  "97": "<h2>97</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">東方問題の発生</u></p>\n<p>て言ってビザンツ皇帝の後継者を称する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア</strong></span>も介入してくる。そうなると、ロシアに勢力拡大させたくない<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イギリス</strong></span>も、「ロシアめ、いい加減にしろ」と言って介入し、イギリスだけに得をさせたくないフランスもくる。</p>\n<p>こうして、<strong class=\"source-bold\">オスマン帝国領内の民族運動にヨーロッパ<ruby>列強<rt>れっきょう</rt></ruby>が介入</strong>して、重大な国際問題になっていったんだ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東方問題</strong></span>だよ。狭い意味では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エジプト＝トルコ戦争</strong></span>だけを指す場合もあるんだけど、一般的には広い意味で、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ギリシア独立戦争</strong></span>から、1877年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>露土<rt>ろと</rt></ruby>戦争</strong></span><strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア＝トルコ戦争</strong></span><strong class=\"source-bold\">】</strong>とその処理のために開かれた1878年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン会議</strong></span>までの列強の対立のことだよ。じゃあ、順に見ていこう。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ギリシア独立戦争で列強の思惑がぶつかり、東方問題が起きた！</strong></span></h4>\n<p>すでにウィーン体制の崩壊<span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第1回</strong></span>でギリシア独立戦争の経過は説明したけど、今回は<strong class=\"source-bold\">国際関係を中心</strong>に見直してみよう。ギリシアが独立戦争を始めると、これを<ruby>潰<rt>つぶ</rt></ruby>したい<strong class=\"source-bold\">オスマン帝国（トルコ）</strong>は、帝国領内の<strong class=\"source-bold\">エジプト</strong>で近代化を進めていた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ムハンマド＝アリー</strong></span>に「ギリシアの独立を潰せ！」って命令し、ムハンマド＝アリーも<strong class=\"source-bold\">シリアの<ruby>割譲<rt>かつじょう</rt></ruby>と引き換えに軍を派遣した</strong>。これに対して、南下政策を進めるロシアはチャンスだと思った。だって、<strong class=\"source-bold\">ロシアは</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ダーダネルス・ボスフォラス海峡</strong></span>を通過して<strong class=\"source-bold\">地中海に進出したい</strong>んだもん。<strong class=\"source-bold\">海峡の両岸はオスマン帝国領</strong>だから、オスマン帝国にいちゃもんつけて、特権や領土を奪えば地中海に進出できる。もはや自由や独立は関係なくなって、<strong class=\"source-bold\">ロシアがギリシア側で参戦</strong>したんだ。</p>\n<h4><strong class=\"source-bold\">〈ギリシア独立戦争〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">エジプト</strong></td><td><strong class=\"source-bold\">オスマン帝国</strong></td></tr><tr><td><strong class=\"source-bold\">ギリシア</strong></td><td><span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">ロシア</strong></span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">イギリス</span></strong></span></td><td><strong class=\"source-bold\">フランス</strong></td></tr></tbody></table></div>\n<p>これに対してイギリスは、「ロシアの南下は潰す！」と思いつつ、だからといってロシアの敵として参戦することはできない。だって<strong class=\"source-bold\">ロシアが支援しているのは「ギリシアの独立」</strong>なんだもん。オスマン帝国側で参戦したら独立を潰す、つまり自由主義を潰すことになっちゃう……。だから<strong class=\"source-bold\">イギリス</strong>はなんとかロシアを抑えこもうと、ロシアと同じく<strong class=\"source-bold\">ギリシア側で参戦</strong>したんだね。あっ、ここから先の戦争、戦闘では<strong class=\"source-bold\">イギリスがついたほうが全部勝ち</strong>。やっぱイギリスは強い！。といっても、必ずしもつねにイギリスが得したわけじゃないんだよ。ギリシア独立戦争で、</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "98": "<h2>98</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第5回</strong></span> ロシアと東方問題</p>\n<p>イギリスはいきなりそれを思い知らされるんだ。</p>\n<p>1829年、<strong class=\"source-bold\">ロシア</strong>は単独でオスマン帝国との間で<strong class=\"source-bold\">アドリアノープル条約</strong>を結んで<strong class=\"source-bold\">ギリシアの独立を承認</strong>させると、<strong class=\"source-bold\">黒海北岸の領土を獲得</strong>するとともに、<strong class=\"source-bold\">黒海とダーダネルス・ボスフォラス海峡の自由航行権</strong>を確保したんだ。これって、<strong class=\"source-bold\">ロシアの南下が成功</strong>したってことだよ。だからこれ以後、イギリスは「ロシアの南下は全部<ruby>阻止<rt>そし</rt></ruby>する！」っていうくらい、ロシアと敵対することになるんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ムハンマド＝アリーとオスマン帝国が<ruby>揉<rt>も</rt></ruby>めて……またまたロシアが得しちゃう！<br>――第1次エジプト＝トルコ戦争</strong></span></h4>\n<p>さて、エジプトの敗戦が新たな問題を引き起こすよ。きっかけは「<strong class=\"source-bold\">シリアの領有権</strong>」をめぐる問題だ。ギリシア独立戦争の時に約束した「シリア<ruby>割譲<rt>かつじょう</rt></ruby>」の認識が、オスマン帝国（トルコ）とムハンマド＝アリーで違うんだよ。<strong class=\"source-bold\">オスマン帝国</strong>は「<strong class=\"source-bold\">勝ったらシリアをあげる</strong>」と約束したつもりだから、戦争で負けた以上、<strong class=\"source-bold\">シリアをあげなくていい</strong>と思ってる。対する<strong class=\"source-bold\">ムハンマド＝アリー</strong>は「<strong class=\"source-bold\">参戦したらシリアをもらえる</strong>（つまり勝ち負けは関係なし）」と思っているから、<strong class=\"source-bold\">シリアをよこせと要求</strong>し始めるよね。この対立から始まったのが、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次エジプト＝トルコ戦争</strong></span>だ。</p>\n<h4><strong class=\"source-bold\">〈第1次エジプト＝トルコ戦争〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">ロシア</strong></span></td><td><strong class=\"source-bold\">オスマン帝国</strong></td></tr><tr><td><strong class=\"source-bold\">エジプト</strong></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">イギリス</span></strong></span></td></tr><tr><td><strong class=\"source-bold\">フランス</strong></td><td><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">オーストリア</strong></span></td></tr></tbody></table></div>\n<p>いざ開戦すると、戦争はエジプトとオスマン帝国の問題というより<strong class=\"source-bold\"><ruby>列強<rt>れっきょう</rt></ruby>の対立に変わってしまう</strong>。まず、ロシアがすごい作戦を思いついた！　たぶん、ムハンマド＝アリーの主張をマネしたんだろうな。「オスマン帝国の味方をするかわりになんかもらえばいい」って考えた<strong class=\"source-bold\">ロシアは</strong>、ギリシア独立戦争から一転、<strong class=\"source-bold\">オスマン帝国を支援</strong>し始めた。一方、エジプトに野心を持っている<strong class=\"source-bold\">フランスはエジプトを支援</strong>し始めた。そして、ロシアがボスフォラス海峡に上陸すると「何をたくらんでるんだ！」と思った<strong class=\"source-bold\">英仏は、オスマン帝国に圧力をかけてエジプトと和解させた</strong>んだよ。</p>\n<p>結果、<strong class=\"source-bold\">戦争そのものはエジプトの勝利</strong>ということになり、<strong class=\"source-bold\">ムハンマド＝アリーのシリア領有権が認められた</strong>んだけど、「なんでエジプトの味方するんだよ！」と思った<strong class=\"source-bold\">オスマン帝国は、英仏に相当ムカついてる</strong>。そこに現れたのがロシア……「英仏っ</p>",
  "99": "<h2>99</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">東方問題の発生</u></p>\n<p>てイヤな奴らだよね。だからボクがキミを助けてあげるよ」。ほら、ここで愛が芽生える。これ、フラれた子の相談に乗ったら付き合っちゃったっていうパターン。こうして、<strong class=\"source-bold\">ロシアとオスマン帝国の相互援助条約</strong>として<strong class=\"source-bold\">ウンキャル＝スケレッシ条約</strong>が結ばれ、ロシアは<strong class=\"source-bold\">ダーダネルス・ボスフォラス海峡のロシア軍艦の独占航行権</strong>を獲得したんだよ。もちろん秘密条項だけど、これって、<strong class=\"source-bold\">勝ってないのにロシアの南下が成功した</strong>！ってことだ。イギリスがキレるのも時間の問題だな……。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">戦闘じゃなくて外交で勝つ！　イギリスは2度同じ失敗はしない<br>――第2次エジプト＝トルコ戦争</strong></span></h4>\n<p>ウンキャル＝スケレッシ条約の秘密条項に気づいたイギリスは、ロシアを<ruby>潰<rt>つぶ</rt></ruby>すための機会をうかがっていたんだけど、再びエジプトとオスマン帝国（トルコ）の関係が悪化して、意外に早くチャンスがくるんだよね。それが「<strong class=\"source-bold\">エジプトとシリアの<ruby>世襲<rt>せしゅう</rt></ruby>権</strong>」をめぐる問題だ。すでに<strong class=\"source-bold\">シリア領有権を獲得したムハンマド＝アリー</strong>がちょっとばかり調子に乗って、<strong class=\"source-bold\">エジプトとシリアの世襲権を要求</strong>（これって、オスマン帝国から独立するって意味だよ）し始めた。もちろん、オスマン帝国はこんなもん認めるわけがない。こうして、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次エジプト＝トルコ戦争</strong></span>が始まったんだ。</p>\n<h4><strong class=\"source-bold\">〈第2次エジプト＝トルコ戦争〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">ロシア</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">イギリス</span></strong></span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">オーストリア</strong></span></td><td><strong class=\"source-bold\">プロイセン</strong></td></tr><tr><td><strong class=\"source-bold\">オスマン帝国</strong></td><td><strong class=\"source-bold\">エジプト</strong></td></tr><tr><td><strong class=\"source-bold\">フランス</strong></td><td></td></tr></tbody></table></div>\n<blockquote><p>ロシアとフランスを両方とも抑え込むイギリス外交に注目だ！</p></blockquote>\n<p>こうなると、再び列強も動き出すよ。まず<strong class=\"source-bold\">フランスが抜け駆け</strong>。<strong class=\"source-bold\">エジプトに接近</strong>して、利権を拡大しようとしていた。もちろん、<strong class=\"source-bold\">ロシアはオスマン帝国を支援</strong>して何かもらい、南下政策を進めようとしている。<strong class=\"source-bold\">イギリスはフランスにもロシアにも得をさせたくない</strong>。こうなると、戦闘で勝ってもほとんど意味がないよね。だって、必ずどっちかが勝つでしょ。そこで一転、<strong class=\"source-bold\">イギリスはオスマン帝国を支援</strong>することにした。そして、<strong class=\"source-bold\">オーストリアとプロイセンを巻き込んで</strong>ロシアにこう持ち掛けたんだ。「オスマン帝国がかわいそうなので、<strong class=\"source-bold\">英・露・墺・普の“4国”</strong>で助けましょう。抜け駆けはダメですよ」ってね。顔で笑ってても、内心は火花バチバチ。だってイギリスは内心、ロシアに対して「1国で勝手なことをしたら、こっ</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "100": "<h2>100</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第5回</strong></span> ロシアと東方問題</p>\n<p>ちの3国で<ruby>潰<rt>つぶ</rt></ruby>すからな」と思っている。ロシアもロシアで「イギリス、余計なことをしやがって」って本音では思っているんだもん。</p>\n<p>そうはいっても表向きは協力した4国は、<strong class=\"source-bold\">オスマン帝国を支援してエジプトを破った</strong>。これだけ組めば勝てるよ。そして<strong class=\"source-bold\">イギリス</strong>は「余計なことをすると4国VS.フランスになりますよ」と言って<strong class=\"source-bold\">フランスを黙らせ</strong>、1840年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロンドン会議</strong></span>を開いた。はっきり言ってイギリスは、ムハンマド＝アリーのことに興味はない。そこで<strong class=\"source-bold\">ムハンマド＝アリー</strong>には<strong class=\"source-bold\">オスマン帝国<ruby>宗主<rt>そうしゅ</rt></ruby>下でエジプト・スーダンの<ruby>世襲<rt>せしゅう</rt></ruby>権</strong>を認め（これで<strong class=\"source-bold\">事実上エジプトは独立</strong>ね）、<strong class=\"source-bold\">シリア領有権は<ruby>放棄<rt>ほうき</rt></ruby></strong>させるっていう、勝ち負けがよくわからない状態にした。とにかくフランスとロシアを抑えればいい。</p>\n<p>でもって、肝心の<strong class=\"source-bold\">フランスとロシアの問題</strong>。とにかくロシアの南下を抑えるために、<strong class=\"source-bold\">あらゆる外国軍艦</strong>（つまりオスマン帝国以外ね）<strong class=\"source-bold\">のダーダネルス・ボスフォラス海峡の通過を禁止</strong>にしたんだ（<strong class=\"source-bold\">ロンドン4国条約</strong>）。そして、翌年にはフランスを加えて<strong class=\"source-bold\">海峡協定</strong>を結び、<strong class=\"source-bold\">ウンキャル＝スケレッシ条約は破棄</strong>されて、<strong class=\"source-bold\">ロシアの南下政策を阻止</strong>するとともに、<strong class=\"source-bold\">フランスを黙らせておいたことでエジプト進出を阻止</strong>することに成功したよ。これって、イギリスが外交で完全に主導権を握り、思ったとおりの結果を得たってことだよね。これを当時の外務大臣の名前を取って「<strong class=\"source-bold\">パーマストン外交の勝利</strong>」なんて呼んでいるよ。</p>\n<h4><strong class=\"source-bold\">〈東方問題（クリミア戦争まで）〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">ロシア帝国</strong></td><td>イスタンブル</td></tr><tr><td><strong class=\"source-bold\">ダーダネルス海峡</strong></td><td><strong class=\"source-bold\">ボスフォラス海峡</strong></td></tr><tr><td><strong class=\"source-bold\">オスマン帝国（トルコ）</strong></td><td><strong class=\"source-bold\">ギリシア</strong></td></tr><tr><td><strong class=\"source-bold\">シリア</strong></td><td>イェルサレム</td></tr><tr><td><strong class=\"source-bold\">エジプト</strong></td><td>黒海</td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">セヴァストーポリ要塞</span></td><td></td></tr><tr><td><span data-source-marker=\"area\" style=\"color:#e52715\">■</span> オスマン帝国（トルコ）領</td><td><span data-source-marker=\"arrow\" style=\"color:#001000\">➜</span> ロシアの南下政策</td></tr></tbody></table></div>\n<blockquote><p>衰退していくオスマン帝国は「<ruby>瀕死<rt>ひんし</rt></ruby>の病人」なんていわれてた……これじゃ、<ruby>列<rt>れっ</rt></ruby><ruby>強<rt>きょう</rt></ruby>の<ruby>餌食<rt>えじき</rt></ruby>だ</p></blockquote>",
  "101": "<h2>101</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">東方問題の発生</u></p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span></h3>\n<h4><strong class=\"source-bold\">東方問題</strong>……<strong class=\"source-bold\">特にロシアとイギリスの動きに注目！</strong></h4>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">●ギリシア独立戦争</strong></span>［1821〜29］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>エジプト＝<span data-source-border=\"gray\" style=\"border:1px solid #777777;padding:0 0.2em\">オスマン帝国</span> vs. <span data-source-border=\"gray\" style=\"border:1px solid #777777;padding:0 0.2em\">ギリシア</span>＝<strong class=\"source-bold\">露・英</strong>・仏</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">アドリアノープル条約</strong>［1829］……ロシア・オスマン帝国間で<ruby>締結<rt>ていけつ</rt></ruby></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ギリシアの独立</strong></span>承認／<span data-source-color=\"green\" style=\"color:#315837\">▶</span>ロシアに黒海北岸を<ruby>割譲<rt>かつじょう</rt></ruby></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">ロシアの</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ダーダネルス・ボスフォラス海峡</strong></span><strong class=\"source-bold\">の自由航行権</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">●第1次エジプト＝トルコ戦争</strong></span>［1831〜33］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">ロシア</strong>＝<span data-source-border=\"gray\" style=\"border:1px solid #777777;padding:0 0.2em\">オスマン帝国</span> vs. <span data-source-border=\"gray\" style=\"border:1px solid #777777;padding:0 0.2em\">エジプト</span>＝<strong class=\"source-bold\">英</strong>・仏・墺</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">ウンキャル＝スケレッシ条約</strong>［1833］……<strong class=\"source-bold\">ロシアとオスマン帝国の</strong>相互援助条約</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">ロシア軍艦の</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ダーダネルス・ボスフォラス海峡</strong></span><strong class=\"source-bold\">の独占航行権</strong>（秘密条項）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">●第2次エジプト＝トルコ戦争</strong></span>［1839〜40］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">露・英</strong>・墺・普＝<span data-source-border=\"gray\" style=\"border:1px solid #777777;padding:0 0.2em\">オスマン帝国</span> vs. <span data-source-border=\"gray\" style=\"border:1px solid #777777;padding:0 0.2em\">エジプト</span>＝フランス</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロンドン会議</strong></span>［1840］……<strong class=\"source-bold\">ロンドン4国条約</strong>を<ruby>締結<rt>ていけつ</rt></ruby></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">ウンキャル＝スケレッシ条約の破棄</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">あらゆる外国軍艦の</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ダーダネルス・ボスフォラス海峡</strong></span><strong class=\"source-bold\">の通過禁止</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>翌年、フランスを加えて<strong class=\"source-bold\">五国海峡協定</strong>成立</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">●クリミア戦争</strong></span>［1853〜56］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">英</strong>・仏・サルデーニャ＝<span data-source-border=\"gray\" style=\"border:1px solid #777777;padding:0 0.2em\">オスマン帝国</span> vs. <span data-source-border=\"gray\" style=\"border:1px solid #777777;padding:0 0.2em\"><strong class=\"source-bold\">ロシア</strong></span></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">セヴァストーポリ<ruby>要塞<rt>ようさい</rt></ruby>の攻防戦</strong>……最大の激戦</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリ条約</strong></span>［1856］……<strong class=\"source-bold\">ロシアの南下が完全に挫折</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">黒海の中立化</strong></span>／<span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モルダヴィア・ワラキア</strong></span><strong class=\"source-bold\">の自治権保障（事実上独立）</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">●<ruby>露土<rt>ろと</rt></ruby>戦争</strong></span><strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア＝トルコ戦争</strong></span><strong class=\"source-bold\">】</strong>［1877］……<strong class=\"source-bold\">各国は<ruby>介入<rt>かいにゅう</rt></ruby>できず</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サン＝ステファノ条約</strong></span>［1878］……<strong class=\"source-bold\">ロシアの南下が大成功</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セルビア・モンテネグロ・ルーマニア</strong></span>の独立</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブルガリア</strong></span>の<strong class=\"source-bold\">領土を拡大</strong>して自治国とし、<strong class=\"source-bold\">ロシアの保護下</strong>に置く</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン会議</strong></span>［1878］……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビスマルク</strong></span>が「<strong class=\"source-bold\">誠実な<ruby>仲介人<rt>ちゅうかいにん</rt></ruby></strong>」として<ruby>仲裁<rt>ちゅうさい</rt></ruby></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セルビア・モンテネグロ・ルーマニア</strong></span>の独立</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブルガリア</strong></span>の<strong class=\"source-bold\">領土を縮小</strong>して、<strong class=\"source-bold\">オスマン帝国宗主下の自治国</strong>とする</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">オーストリア</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボスニア・ヘルツェゴヴィナ</strong></span>の<strong class=\"source-bold\"><ruby>統治<rt>とうち</rt></ruby>権</strong>を獲得</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">イギリス</strong>はキプロス島の<strong class=\"source-bold\">行政権</strong>を獲得</p></blockquote>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ダーダネルス・ボスフォラス海峡</strong></span>は「<strong class=\"source-bold\">自由航行権</strong><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">独占航行権</strong><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">通過禁止</strong>」と変わる！　ロシアにとっては「<strong class=\"source-bold\">成功</strong><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">成功</strong><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">挫折</strong>」だ</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "102": "<h2>102</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第5回</strong></span> ロシアと東方問題</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <strong class=\"source-bold\">クリミア戦争とロシアの改革</strong></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ロシアとオスマン帝国が聖地管理権をめぐって対立！　こりゃ戦争か？</strong></span></h4>\n<p><strong class=\"source-bold\">エジプト＝トルコ戦争によって南下政策に挫折したロシア</strong>だったけど、別に<ruby>諦<rt>あきら</rt></ruby>めたわけじゃないよ。次に進出できるチャンスをずっとうかがっていたんだ。次に起こる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">クリミア戦争</strong></span>は、ロシアにしてみれば勝てるはずの戦争だったのに……歴史はそうは動かなかったんだね。</p>\n<p>じゃあ、まずは背景から話していこう。そもそもクリミア戦争のきっかけは、<strong class=\"source-bold\">聖地管理権問題</strong>だ。<strong class=\"source-bold\">聖地とはイェルサレム</strong>のことで、領土としては16世紀以来、ずっとオスマン帝国（トルコ）領なんだけど、イェルサレムには<strong class=\"source-bold\">キリスト教、イスラーム教、ユダヤ教の3つの宗教の聖地</strong>があるから、いくらオスマン帝国領とはいっても聖地巡礼に訪れるキリスト教徒もたくさんいたんだよ。そこで<strong class=\"source-bold\">聖地管理権</strong>という問題が出てくる。要は、<strong class=\"source-bold\">オスマン帝国領のイェルサレム</strong>のうち、「<ruby>聖墳墓<rt>せいふんぼ</rt></ruby>教会（イエスの墓があるんだよ）を中心とする<strong class=\"source-bold\">キリスト教の聖地の部分だけはキリスト教徒が管理</strong>する」っていうのが、聖地管理権だ。そして、16世紀以来<strong class=\"source-bold\">オスマン帝国と同盟を結んだフランス</strong>が持っていたんだけど、18世紀の<strong class=\"source-bold\">フランス革命</strong>の時に、フランスはキリスト教否定運動をやったもんだから、「フランスがキリスト教を捨てるなら、ロシアを中心にギリシア正教が持つべきである」として、<strong class=\"source-bold\">ロシアがオスマン帝国から聖地管理権を獲得</strong>していたんだ。</p>\n<p>ところが、フランスで<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナポレオン3世</strong></span>が皇帝になると、まぁ人気取りだろうね、オスマン帝国に対し「もともとフランスが持っていたんだから、フランスに返せ！」と要求して、<strong class=\"source-bold\">フランスが取得</strong>してしまった。これに対し<strong class=\"source-bold\">ロシアのニコライ1世</strong>は「聖地管理権を失ったらギリシア正教が<ruby>弾圧<rt>だんあつ</rt></ruby>されるではないかぁ、許せん」といちゃもんをつけ、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ギリシア正教徒の保護</strong></span>を口実に<strong class=\"source-bold\">オスマン帝国に<ruby>宣戦<rt>せんせん</rt></ruby></strong>し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">クリミア戦争</strong></span>が<ruby>勃発<rt>ぼっぱつ</rt></ruby>した。あっ、これはただのいちゃもんだよ。確かに、これまでオスマン帝国領内でギリシア正教徒の反乱はちょこちょこ起きてたけど、この時は<strong class=\"source-bold\">ロシアが参戦するほどの問題は起きていない</strong>からね。</p>\n<h4><strong class=\"source-bold\">〈クリミア戦争〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">イギリス</span></strong></span></td><td><strong class=\"source-bold\">フランス</strong></td></tr><tr><td><strong class=\"source-bold\">サルデーニャ</strong></td><td><strong class=\"source-bold\">オスマン帝国</strong></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">ロシア</strong></span></td><td></td></tr></tbody></table></div>",
  "103": "<h2>103</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">クリミア戦争とロシアの改革</u></p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ロシアvs.オスマン帝国のはずが、一大国際戦争に発展！――クリミア戦争</strong></span></h4>\n<p>ロシアにしてみれば、「オスマン帝国くらい軽く倒せる！」って思ってたんだろうね。確かに開戦した1853年は、ロシアが優勢だったよ。でも、翌年になって状況は一変。だって聖地管理権で<ruby>揉<rt>も</rt></ruby>めた相手は<strong class=\"source-bold\">フランス</strong>だよ。しかも、この戦争にロシアが勝てば南下政策が進むのが目に見えてるから、<strong class=\"source-bold\">イギリス</strong>が黙ってない。</p>\n<p>こうして<strong class=\"source-bold\">オスマン帝国側で英仏</strong>、さらにはイタリア統一を狙う<strong class=\"source-bold\">サルデーニャ王国も参戦</strong>してくると、気づいた時には<strong class=\"source-bold\">ヨーロッパ<ruby>列強<rt>れっきょう</rt></ruby>間の一大国際戦争</strong>になり、<strong class=\"source-bold\">ロシアには絶望的な敗北が待っていた</strong>。だって、産業革命の進んだイギリスの軍艦は鋼鉄製のしかも蒸気船。こんなのがバンバカきたらたまんないよ。対するロシア軍艦は……半分以上が木の<ruby>帆船<rt>はんせん</rt></ruby>。これじゃあ<ruby>大砲<rt>たいほう</rt></ruby>1発で沈んじゃう。しかも兵士は<ruby>農奴<rt>のうど</rt></ruby>を無理やり集めた軍団だから、みんな疲れ切ってやる気なし。最大の激戦となった<strong class=\"source-bold\">セヴァストーポリ<ruby>要塞<rt>ようさい</rt></ruby>の攻防戦</strong>では、1年間の激戦でロシア軍は10万人以上の死者を出し、<ruby>惨敗<rt>さんぱい</rt></ruby>した。さらに、戦争中に<strong class=\"source-bold\">ニコライ1世が急死</strong>してしまう……。かわいそうなのは残された息子の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アレクサンドル2世</strong></span>だよ。皇帝として最初に味わったのが無惨な敗北になったんだ。</p>\n<blockquote><p>クリミア戦争では、イギリスの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナイティンゲール</strong></span>が従軍看護で活躍したよ！　この影響を受けたのがデュナンだ</p></blockquote>\n<p>こうして<strong class=\"source-bold\">ロシアが敗北</strong>して1856年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリ条約</strong></span>が結ばれ、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">黒海の中立化</strong></span>（<strong class=\"source-bold\">軍艦の航行禁止と、軍事基地の撤去</strong>）、ドナウ川航行の自由、ロシアの南ベッサラビア<ruby>放<rt>ほう</rt></ruby><ruby>棄<rt>き</rt></ruby>、さらに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モルダヴィア・ワラキア</strong></span>（のちのルーマニアね）<strong class=\"source-bold\">の自治権が保障</strong>されて（事実上の独立）、<strong class=\"source-bold\">ロシアの南下政策は完全に挫折</strong>した。</p>\n<p>そして、<strong class=\"source-bold\">クリミア戦争にはもう1つ重要な意味</strong>があるよ。それはウィーン体制以来のヨーロッパの国際関係の基本原則だった「<strong class=\"source-bold\">勢力<ruby>均衡<rt>きんこう</rt></ruby></strong>」<strong class=\"source-bold\">が崩れた</strong>ってことだ。これまで列強は勢力均衡を原則として、なるべく直接対決をしないように、あるいはどこか1国だけが強国にならないように、各国のバランスをとってきた。そして、その体制を支えていた国は<strong class=\"source-bold\">自由主義の中心であるイギリス</strong>と、<strong class=\"source-bold\">保守反動の中心であるロシア</strong>だったんだよ。ところがロシアの惨敗で<strong class=\"source-bold\">イギリスとロシアが支えていた勢力均衡が崩れてしまった</strong>んだね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">危機感を持ったアレクサンドル2世が、改革に動き出した！</strong></span></h4>\n<p><strong class=\"source-bold\">クリミア戦争で惨敗</strong>したロシア皇帝<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アレクサンドル2世</strong></span>は、相当なショックを受けたんだ。いくら産業革命が進んでいないとはいえ、まさかイギリスやフランスにここまでの差をつけられているとは思ってもいなかった。もはや、<strong class=\"source-bold\">ロシアが遅れた国と認めるしかない</strong>……。この屈辱を晴らすためには、改革によって近代国家に生まれ変わるしかないよね。こうして改革路線を宣言したアレクサンドル2世に</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "104": "<h2>104</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第5回</strong></span> ロシアと東方問題</p>\n<p>よって、<strong class=\"source-bold\">ロシアの「大改革」</strong>が始まった。そしてついに……これまでロシア社会の発展を妨げてきた<strong class=\"source-bold\"><ruby>農奴<rt>のうど</rt></ruby>制に手をつけた</strong>。これは彼が皇太子の時代に農奴制を題材とした<strong class=\"source-bold\">トゥルゲーネフ</strong>の短編小説集<strong class=\"source-bold\">『<ruby>猟人<rt>りょうじん</rt></ruby>日記』</strong>を読んでショックを受けたことが影響したともいわれているよ。</p>\n<p>1861年、アレクサンドル2世は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">農奴解放令</strong></span>を発布し、<strong class=\"source-bold\">領主制を廃止</strong>して<strong class=\"source-bold\">農奴に<ruby>無<rt>む</rt></ruby><ruby>償<rt>しょう</rt></ruby>（タダ）で人格的な自由を与える</strong>こととした。これで、農奴は自由な身分になったんだよ。これは、ロシアにしてみれば革命的な事件だ！　ただねぇ……そこはやはりロシアなんだよ。<strong class=\"source-bold\">農民に土地が与えられた</strong>んだけど、<strong class=\"source-bold\">土地はタダではない</strong>んだよ。農民は<strong class=\"source-bold\">土地の代金（買い取り金）</strong>を払うことになったんだけど、こんなもん払えるわけない。でも払わなきゃいけない。農民は「払えないんですけど……」と言ったら、「それならローン（教科書とかでは<ruby>年賦<rt>ねんぷ</rt></ruby>って書いてあるよ）で払え」と言われた。だからこの後49年間もローンを払い続けることになるんだけど、払えない場合には<strong class=\"source-bold\">土地所有権は農村共同体（ミール）のものになり</strong>、買い戻し金の支払いもミールの連帯責任になった。だから、農民はミールに縛りつけられて、完全に自由になったわけじゃないんだよ。しかも、もらえた土地が狭くて、結局は貴族の土地でも働かなきゃダメだったし。</p>\n<p>ただ、この<strong class=\"source-bold\">農奴解放で変わったこと</strong>もあるよね。たいていの教科書で「農奴解放令は、<strong class=\"source-bold\">ロシアの資本主義発達の出発点</strong>になった」と書いてあるんだけど、別に農奴を解放した瞬間から産業革命が始まるわけじゃないよ。身分的に自由になった農奴は豊かになれなかったけど、少なくとも「<strong class=\"source-bold\">やめたければ農民をやめられる自由</strong>」だけは手に入れたんだ。「もう土地なんていりません。ホームレスになってもいいから農民をやめます」って言えば、ほかのところ、例えば都市に引っ越すことはできる。あるいは、ホームレスにならなくても出稼ぎには行ける。<strong class=\"source-bold\">彼らが労働者になれば産業革命が進む</strong>、ってことだ。</p>\n<p>アレクサンドル2世は、ほかにも<strong class=\"source-bold\">地方自治の改革</strong>を進めたり、<strong class=\"source-bold\">国内の鉄道建設</strong>を進めたり、さまざまな改革を進めたんだけど、1863年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーランド反乱</strong></span>を<ruby>鎮圧<rt>ちんあつ</rt></ruby>するのにてこずったこともあって、結局<strong class=\"source-bold\">改革をやめて、もとの専制政治に逆戻り</strong>し始めた。やっぱ、このへんはロシア皇帝だよなぁ。</p>\n<blockquote><p>やっと農奴解放が実現したけど、農民の生活は全然楽にならないよ……</p></blockquote>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">農村からの改革を目指し、ナロードニキが農村に入った！</strong></span></h4>\n<p><strong class=\"source-bold\">農奴解放令が出されたあとも、ロシアの農民はずっと貧乏なまま</strong>だった。だって、これまでの借金や土地の買い戻し金、さらに税金と、重い負担が続いたんだもん。こうした状況を見た<strong class=\"source-bold\">都市の知識人たち（インテリゲンツィア）</strong>、特に貴族や新興の市民階級（要は都市の金持ち連中ね）の息子たちは「なんでロシアの農民はこ</p>",
  "105": "<h2>105</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">露土戦争</u></p>\n<p>んなに貧乏なんだろう？　彼らを救うには、資本主義の段階を飛ばして、一気に<strong class=\"source-bold\">農村を拠点にした社会主義にする</strong>しかない！」と思って、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴ＝ナロード</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人民の中へ</strong></span>）」をスローガンに農村へと入っていった。彼らを<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナロードニキ</strong></span>というんだ。</p>\n<p>ナロードニキの連中は、農民にしてみれば上から目線なんだけど、「農民が自由になれないのは、自由の素晴らしさを知らないからだ。農民が豊かになれないのは、農民に知識がないからだ」って思って、<strong class=\"source-bold\">農民に自由や平等、それに社会主義の素晴らしさを教える<ruby>啓蒙<rt>けいもう</rt></ruby>運動</strong>をやったんだけど……、農民にしてみればいい迷惑。だって、ロシアの農民って今日の晩飯が食えるか食えないかの瀬戸際で生きてるようなヤツらだよ。全然話を聞いてくれないし、やる気もない……しまいには「自由がわかったって、飯が食えないよ」って、怒り始めた。</p>\n<p>こうして<strong class=\"source-bold\">農民の反発で運動が挫折</strong>すると、<strong class=\"source-bold\">ナロードニキの連中は逆ギレ</strong>したんだよ。「農民が話を聞かないのは、今の社会が悪い！　政府が悪い！」って思って、国家権力は全部いらないと考える<strong class=\"source-bold\">無政府主義【アナーキズム】</strong>や、あらゆる権力も権威も秩序も全部いらないって考える<strong class=\"source-bold\"><ruby>虚無<rt>きょむ</rt></ruby>主義【ニヒリズム】</strong>に走り始めた。これを本当に実現しようとすると<strong class=\"source-bold\">テロリズム</strong>しかなくなるよ……。だから、<strong class=\"source-bold\">一部のナロードニキはテロリストになって</strong>、ついには爆弾使って<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アレクサンドル2世を暗殺</strong></span>してしまったんだよ。あっ、ここ時代が前後しちゃったんだけど、暗殺されたのは、次に話す<strong class=\"source-bold\"><ruby>露土<rt>ろと</rt></ruby>戦争のあと（1881年）</strong>だから気をつけてね。</p>\n<p>さて、その後のナロードニキなんだけど、<strong class=\"source-bold\">もちろん全員がテロリストになったわけじゃない</strong>。そんなことになったら大事件だよ。テロリストにならなかった連中は「自分たちが間違っていた」って反省して、農民の願いである「<strong class=\"source-bold\">自由と土地</strong>」に目を向けて、<strong class=\"source-bold\">農民たちの生活を向上</strong>させるために<ruby>頑張<rt>がんば</rt></ruby>ったから、一定の成果を上げた。彼らは1901年に結成される<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エスエル</strong></span><strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会革命党</strong></span><strong class=\"source-bold\">】</strong>のもとになったよ。</p>\n<blockquote><p>農民がナロードニキに反発するのも無理ないよ……だって、ナロードニキって金持ちの息子だもん</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <strong class=\"source-bold\">露土戦争</strong></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">南下に<ruby>挫折<rt>ざせつ</rt></ruby>したロシアに、またまたチャンスがめぐってきた！</strong></span></h4>\n<p>じゃあ、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東方問題</strong></span>に戻ろう。クリミア戦争の敗北から約20年、ロシアはバルカン進出をやらなかった。まぁ時が過ぎ去るのを待ってたんだろうね、「みんな忘れろー」ってさ。その間、<strong class=\"source-bold\">東アジアでは中国（<ruby>清<rt>シン</rt></ruby>）への進出</strong>を進めたり、<strong class=\"source-bold\">中央アジアではウズベク3ハン国</strong>を支配下に置いたりしてたんだけど、やっぱバルカンに行きたい！　そう思っていたロシアに、再びチャンスがめぐってきたのが、1875年だ。</p>\n<p>まず、バルカン半島でオスマン帝国（トルコ）の支配下にあった<strong class=\"source-bold\">ボスニア・ヘル</strong></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "106": "<h2>106</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第5回</strong></span> ロシアと東方問題</p>\n<p><strong class=\"source-bold\">ツェゴヴィナ</strong>で反乱が起こった。彼らはオスマン帝国から独立したかったんだ。そして、反乱が隣の国<strong class=\"source-bold\">ブルガリア</strong>に飛び火して独立運動が起きた。しかもこの地域に住んでいる<strong class=\"source-bold\">南スラヴ人はギリシア正教徒が多い</strong>から、同じくギリシア正教徒が多いロシア国内では「ギリシア正教徒を助けろ〜」って運動が始まったんだ。こうして<strong class=\"source-bold\">ロシア</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ギリシア正教徒の保護</strong></span>を口実に、独立運動を支援するという名目で<strong class=\"source-bold\">オスマン帝国と開戦</strong>した。これが1877年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>露土<rt>ろと</rt></ruby>戦争</strong></span><strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア＝トルコ戦争</strong></span><strong class=\"source-bold\">】</strong>だよ。</p>\n<h4><strong class=\"source-bold\">〈露土戦争【ロシア＝トルコ戦争】〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">オスマン帝国</strong></td><td><span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">ロシア</strong></span></td></tr></tbody></table></div>\n<blockquote><p>クリミア戦争の時の「ギリシア正教徒保護」と状況が違うよ。今回は本当に反乱が起きてる！</p></blockquote>\n<p>この戦争は、本当に<strong class=\"source-bold\">ロシアVS.オスマン帝国だけの戦争</strong>になったんだよ。つまり、<strong class=\"source-bold\">イギリスが参戦してない</strong>ってことだ。だって、本当に起きている<strong class=\"source-bold\">独立運動を支援してるから自由主義運動</strong>でしょ。イギリスは、まさか自由主義を<ruby>弾圧<rt>だんあつ</rt></ruby>するわけにもいかず、「ロシアめ、地中海には絶対出さん！」と、黒海の出口に軍艦を待機させたけど、結局どうするか迷っていたんだよ。そうこうしているうちにロシアがイスタンブルに迫り、<strong class=\"source-bold\">イギリスが出てくる前に急いでオスマン帝国と<ruby>講和<rt>こうわ</rt></ruby></strong>したよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">本当は南下に大成功したのに……ビスマルクに邪魔された！</strong></span></h4>\n<p>こうして結ばれた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サン＝ステファノ条約</strong></span>では、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セルビア</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モンテネグロ</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ルーマニア</strong></span><strong class=\"source-bold\">の独立</strong>と、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブルガリア</strong></span>の<strong class=\"source-bold\">領土を拡大</strong>して自治国とし、<strong class=\"source-bold\">ロシアの保護下に置く</strong>ことが決まったんだ。これって<strong class=\"source-bold\">ロシアの南下が大大大成功</strong>♪　ちょっと地図<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">➡P.107</strong></span>を見てごらん。</p>\n<p>ブルガリアの領土が地中海まで広がってるでしょ。これがロシアの保護下ってことは、<strong class=\"source-bold\">ロシアが地中海進出に成功</strong>したってことだよ。この結果を見た<strong class=\"source-bold\">イギリスとオーストリア</strong>がブチ切れた！「もう勘弁ならん。ロシアを<ruby>潰<rt>つぶ</rt></ruby>す！」って怒っている。<strong class=\"source-bold\">この事態を<ruby>仲介<rt>ちゅうかい</rt></ruby>したのは</strong>ドイツの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビスマルク</strong></span>だ。</p>\n<p>ビスマルクは「<strong class=\"source-bold\">誠実な仲介人</strong>」と称して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン会議</strong></span>を開催し、イギリス、オーストリアとロシアの対立を仲介したんだけど、ほぼ全面的に<strong class=\"source-bold\">イギリスとオーストリアの味方</strong>をした。<strong class=\"source-bold\">サン＝ステファノ条約</strong>を<ruby>破棄<rt>はき</rt></ruby>させて<ruby>締結<rt>ていけつ</rt></ruby>した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン条約</strong></span>では、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セルビア</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モンテネグロ</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ルーマニア</strong></span><strong class=\"source-bold\">の独立</strong>はそのままだったけど、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブルガリア</strong></span>の<strong class=\"source-bold\">領土は大幅に縮小</strong>し、しかも<strong class=\"source-bold\">トルコの<ruby>宗主<rt>そうしゅ</rt></ruby>下での自治国</strong>とした。これって、ロ</p>",
  "107": "<h2>107</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">露土戦争</u></p>\n<p><strong class=\"source-bold\">シアの南下を完全に挫折させた</strong>ってことだよね。そして、<strong class=\"source-bold\">オーストリア</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボスニア・ヘルツェゴヴィナ</strong></span>の<ruby>統治<rt>とうち</rt></ruby>権を獲得したのはビスマルクがあげたお土産。一方イギリスはオスマン帝国との協定で、<strong class=\"source-bold\">キプロス島</strong>の行政権を手に入れた。だから、この時出席した<strong class=\"source-bold\">イギリス首相</strong>の<strong class=\"source-bold\">ディズレーリ</strong>は、ビスマルクに好意的になったってわけ。でも、ロシアにはクリミア戦争で失ったベッサラビアの一部を返しただけだったから、ロシアはマジで怒った。「ビスマルク、イヤなヤツ！」ってね。こうして、<strong class=\"source-bold\">ロシアとドイツの関係が悪化</strong>して、このあとの国際関係に影響するんだ。</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">オーストリア=ハンガリー帝国</strong></td><td><strong class=\"source-bold\">ロシア帝国</strong></td></tr><tr><td><strong class=\"source-bold\">ボスニア・ヘルツェゴヴィナ</strong></td><td><strong class=\"source-bold\">ルーマニア</strong></td></tr><tr><td><strong class=\"source-bold\">セルビア</strong></td><td><strong class=\"source-bold\">ブルガリア</strong></td></tr><tr><td><strong class=\"source-bold\">東ルメリア</strong></td><td><strong class=\"source-bold\">マケドニア</strong></td></tr><tr><td><strong class=\"source-bold\">モンテネグロ</strong></td><td><strong class=\"source-bold\">オスマン帝国（トルコ）</strong></td></tr><tr><td><strong class=\"source-bold\">ギリシア</strong></td><td><strong class=\"source-bold\">キプロス島</strong></td></tr><tr><td>地中海</td><td>黒海</td></tr><tr><td><span data-source-marker=\"boundary\" style=\"color:#e52715\">◯</span> サン＝ステファノ条約でのブルガリア国境（大ブルガリア）</td><td></td></tr><tr><td><span data-source-marker=\"area\" style=\"color:#f0a0a0\">■</span> ベルリン条約後のブルガリアの領域</td><td></td></tr><tr><td><span data-source-marker=\"hatch\" style=\"color:#f0a0a0\">▥</span> サン＝ステファノ条約での独立国</td><td></td></tr></tbody></table></div>\n<p>さて、これでロシアと東方問題はおしまい！　国際関係がちょっと複雑だったから、しっかり見直してね。それじゃあ、最後に年号check！</p>\n<h3><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">!!</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">年号のツボ</strong></span></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ロンドン会議</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1840</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby>番<rt>8</rt></ruby><ruby>弱<rt>4</rt></ruby><ruby>れ<rt>0</rt></ruby></strong></span>　ロシアの南下）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">クリミア戦争</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1853</strong></span>］（クリミア戦争　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby>発<rt>8</rt></ruby><ruby>誤<rt>5</rt></ruby><ruby>算<rt>3</rt></ruby></strong></span>）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>農奴<rt>のうど</rt></ruby>解放令</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1861</strong></span>］（土地は有償　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>い<rt>1</rt></ruby><ruby>や<rt>8</rt></ruby><ruby>無<rt>6</rt></ruby></strong></span>理<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>言<rt>1</rt></ruby></strong></span>うな）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">露土戦争</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1877</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>い<rt>1</rt></ruby><ruby>や<rt>8</rt></ruby><ruby>な<rt>7</rt></ruby></strong></span>ん<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>な<rt>7</rt></ruby></strong></span>んだ　大ブルガリア）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ベルリン会議</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1878</strong></span>］（ロシアにも　ビスマルクは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>イ<rt>1</rt></ruby><ruby>ヤ<rt>8</rt></ruby><ruby>な<rt>7</rt></ruby><ruby>ヤ<rt>8</rt></ruby></strong></span>ツ）</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">➡</span>社会主義者にも<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>イ<rt>1</rt></ruby><ruby>ヤ<rt>8</rt></ruby><ruby>な<rt>7</rt></ruby><ruby>ヤ<rt>8</rt></ruby></strong></span>ツだ（<strong class=\"source-bold\">社会主義者<ruby>鎮圧<rt>ちんあつ</rt></ruby>法</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1878</strong></span>］と同じ年）</p></blockquote>\n<p>次回は<strong class=\"source-bold\">19世紀のヨーロッパ文化史</strong>だよ。ジャンルが変わると、ちょっと気分転換になるんじゃないかな？　次回も<ruby>頑張<rt>がんば</rt></ruby>っていこう〜。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>"
};

